import json,re,sys
K=['bg','sky','card','soft','line','edge','fg','muted','faint','accent','accent-ink','on-accent','now-bg','now-ink','late','ok','inverse-bg','inverse-fg']
def P(s):  # "bg sky card ..." then areas "hoa:ink/bg ..." then shadow
    v=s.split()
    d=dict(zip(K,v[:18]))
    for a in v[18:23]:
        n,c=a.split(':'); ink,bg=c.split('/'); d['a-'+n]=ink; d['a-'+n+'-bg']=bg
    d['shadow']=v[23].replace('_',' ')
    return d
