def block(sel,d,scheme):
    return sel+' {\n'+''.join(f'  --{k}: {v};\n' for k,v in d.items())+f'  color-scheme: {scheme};\n}}\n'
css='''/* Life Dashboard color palettes (generated by scripts/palettes.py; run it from the project folder after editing).
   html[data-palette] picks the palette (Settings › Colors, default Coastal);
   html[data-theme=day|night] follows your local sunrise and sunset (public/theme.js). */
'''
css+=block(':root',pal[0][2],'light')+block(':root[data-theme="night"]',pal[0][3],'dark')
for key,name,day,night in pal:
    css+=block(f':root[data-palette="{key}"]',day,'light')+block(f':root[data-palette="{key}"][data-theme="night"]',night,'dark')
s=open('public/style.css').read()
start=s.index('/* Life Dashboard'); end=s.index('* { box-sizing')
open('public/style.css','w').write(s[:start]+css+'\n'+s[end:])
meta=[{'key':k,'name':n,'sky':[d['sky'],nt['sky']],'swatches':[d['bg'],d['now-bg'],d['inverse-bg'],d['accent'],nt['bg']]} for k,n,d,nt in pal]
